                    return 0;
                }

                return ($a['age'] < $b['age']) ? -1 : 1;
            });

            return $sorted_set;
            break;
        default:
            throw new InvalidArgumentException("Invalid order: {$order}. Use 'asc' or 'desc'.");
    }
}

